import{H as e,V as t,j as n,tt as r}from"./chunks/framework.CtsVvn0U.js";var i=JSON.parse(`{"title":"什么是 MCP Kit？","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"zh/guide/what-is-mcp-kit.md","filePath":"zh/guide/what-is-mcp-kit.md"}`),a={name:`zh/guide/what-is-mcp-kit.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /mcp-kit/zh/guide/what-is-mcp-kit.md for this page in Markdown format</div><h1 id="什么是-mcp-kit" tabindex="-1">什么是 MCP Kit？ <a class="header-anchor" href="#什么是-mcp-kit" aria-label="Permalink to “什么是 MCP Kit？”">​</a></h1><p>MCP Kit 是一个面向模型上下文协议（Model Context Protocol，MCP）应用的交互式脚手架 CLI。它会根据设置向导中的选择，生成源码、脚本、测试和说明相互匹配的可开发服务端或客户端。</p><h2 id="可以生成什么" tabindex="-1">可以生成什么？ <a class="header-anchor" href="#可以生成什么" aria-label="Permalink to “可以生成什么？”">​</a></h2><p>MCP Kit 支持 MCP 集成的两端：</p><ul><li><strong>MCP 服务端</strong>：注册工具、资源和提示，并通过 STDIO、Streamable HTTP 或同时通过两者提供能力。</li><li><strong>MCP 客户端</strong>：包含连接辅助函数和完整示例，可发现并使用服务端提供的能力。</li></ul><p>每种项目都可选择 TypeScript 或 JavaScript。生成的代码使用现代 ES 模块，并包含构建与本地开发脚本。</p><h2 id="不是空壳-而是可运行示例" tabindex="-1">不是空壳，而是可运行示例 <a class="header-anchor" href="#不是空壳-而是可运行示例" aria-label="Permalink to “不是空壳，而是可运行示例”">​</a></h2><p>配套的服务端与客户端模板演示了一条端到端知识库工作流：</p><ol><li>客户端调用 <code>search_documents</code> 工具。</li><li>工具返回结构化匹配结果和稳定的 <code>kb://documents/{documentId}</code> 资源 URI。</li><li>客户端读取选中的 Markdown 资源。</li><li>客户端获取附带该资源的 <code>review_document</code> 提示。</li></ol><p>该示例结果确定，不依赖外部数据库或 API。你可以先把它作为可运行参考，再替换成自己的领域逻辑。</p><h2 id="传输方式" tabindex="-1">传输方式 <a class="header-anchor" href="#传输方式" aria-label="Permalink to “传输方式”">​</a></h2><ul><li><strong>STDIO</strong> 面向本地进程集成，生成的服务端通过标准输入和标准输出通信。</li><li><strong>Streamable HTTP</strong> 在 <code>/mcp</code> 暴露 MCP 端点；开发服务器默认监听 <code>8401</code> 端口。</li></ul><p>同时选择两种传输方式时，它们会保留独立实现，并分别提供开发脚本。</p><h2 id="标准与自定义配置" tabindex="-1">标准与自定义配置 <a class="header-anchor" href="#标准与自定义配置" aria-label="Permalink to “标准与自定义配置”">​</a></h2><p><strong>Standard</strong> 配置会启用推荐的工程工具：</p><ul><li>GitHub Actions</li><li>Vitest</li><li>MCP Inspector（仅服务端）</li><li>ESLint、Prettier 与 lint-staged</li><li>Commitlint</li><li>变更日志工具</li></ul><p><strong>Custom</strong> 配置允许自由组合这些插件，也可以全部不选。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><p>继续阅读<a href="./getting-started.html">入门指南</a>，生成并运行一个项目。</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};